package org.xingmu.tv;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class ViewingModesTest {
 @Test public void txtAndM3uSubscriptionsProduceSameChannelId()throws Exception{List<CatalogItem> txt=CatalogParser.parse(LiveSubscription.parse("央视频道,#genre#\nCCTV1,https://example.org/live.php?id=1\nCCTV1,https://backup.example.org/live.m3u8\n坏地址,udp://bad\n").json);List<CatalogItem> m3u=CatalogParser.parse(LiveSubscription.parse("#EXTM3U\n#EXTINF:-1 group-title=\"央视频道\",CCTV1\nhttps://example.org/live.php?id=1\n#EXTINF:-1 group-title=\"央视频道\",CCTV1\nhttps://backup.example.org/live.m3u8\n").json);assertEquals(1,txt.size());assertEquals(txt.get(0).id,m3u.get(0).id);assertEquals(2,txt.get(0).urls.size());assertEquals("直播电视 · zbds",txt.get(0).source);}
 @Test public void subscriptionKeepsCustomUserAgentAndSkipsBadRows()throws Exception{List<CatalogItem> items=CatalogParser.parse(LiveSubscription.parse("\ufeff#EXTM3U\n#EXTINF:-1 group-title=\"卫视频道\" http-user-agent=\"aliplayer\",浙江卫视\nhttps://example.org/zj\n#EXTINF:-1,坏\nudp://unsupported\n").json);assertEquals(1,items.size());assertEquals("aliplayer",items.get(0).userAgent);assertEquals("卫视频道",TvChannelGroup.of(items.get(0)));}
 @Test public void vlcUserAgentDirectiveIsKept()throws Exception{CatalogItem item=CatalogParser.parse(LiveSubscription.parse("#EXTM3U\n#EXTINF:-1,CCTV1\n#EXTVLCOPT:http-user-agent=custom-player\nhttps://example.org/live\n").json).get(0);assertEquals("custom-player",item.userAgent);}
 @Test public void channelGroupsMatchTvRemoteMenu(){assertEquals("央视频道",TvChannelGroup.of(channel("CCTV6","电影","domestic")));assertEquals("国外频道",TvChannelGroup.of(channel("BBC","新闻","foreign")));assertEquals("少儿频道",TvChannelGroup.of(channel("动画影院","其他","domestic")));assertEquals("戏曲频道",TvChannelGroup.of(channel("京剧频道","其他","domestic")));}
 @Test public void sourcePacksMatchUserAddresses(){assertEquals(14,FilmPackRepository.NAMES.length);assertEquals(FilmPackRepository.NAMES.length,FilmPackRepository.URLS.length);assertEquals("极恶论坛-饭太硬",FilmPackRepository.NAMES[1]);assertEquals("http://home.jundie.top:81/top98.json",FilmPackRepository.URLS[3]);for(int n=1;n<FilmPackRepository.URLS.length;n++)assertTrue(CatalogParser.safeMediaUrl(FilmPackRepository.URLS[n]));}
 @Test public void movieDetailsKeepPosterAndCast()throws Exception{VodApi.Movie m=VodApi.parse("{\"list\":[{\"vod_id\":1,\"vod_name\":\"测试\",\"vod_pic\":\"https://example.org/poster.jpg\",\"vod_actor\":\"演员\",\"vod_area\":\"中国大陆\",\"vod_content\":\"<p>剧情</p>\"}]}").get(0);assertEquals("https://example.org/poster.jpg",m.poster);assertEquals("演员",m.actor);assertEquals("中国大陆",m.area);assertEquals("<p>剧情</p>",m.summary);}
 @Test public void queryRemovesStaleCategoryBeforeBrowsing()throws Exception{String query=VodApi.query("https://example.org/api?ac=list&t=2&pg=3&token=test","t","6");assertFalse(query.contains("t=2"));assertFalse(query.contains("pg=3"));assertTrue(query.contains("t=6"));assertTrue(query.contains("token=test"));}
 private CatalogItem channel(String name,String category,String section){return new CatalogItem("test",name,section,category,"中国","https://example.org/live","stream","test","test");}
}
